import { TestApp } from '@guren/testing'
import app from './src/app.js'

async function testApi() {
  const http = await TestApp.fromApp(app)

  // Test valid request
  const response = await http.get('/api/posts?page=1')
  const json = await response.body?.json()
  console.log('Response structure:', {
    hasData: Array.isArray(json?.data),
    hasMeta: json?.meta !== undefined,
    hasCurrentPage: json?.meta?.currentPage !== undefined,
    hasLastPage: json?.meta?.lastPage !== undefined,
    hasPerPage: json?.meta?.perPage !== undefined,
    hasTotal: json?.meta?.total !== undefined,
  })

  // Test author filtering
  const authorResponse = await http.get('/api/posts?author=1')
  const authorJson = await authorResponse.body?.json()
  console.log('Author filter works:', Array.isArray(authorJson?.data))
}

testApi().catch(console.error)
EOF
